import time

class CredentialCache:
    def __init__(self, ttl=3600):
        self.cache = {}  # {username: (password_hash, timestamp)}
        self.ttl = ttl

    def get(self, username):
        if username in self.cache:
            password_hash, timestamp = self.cache[username]
            if time.time() - timestamp < self.ttl:
                return password_hash
            else:
                del self.cache[username]
        return None

    def set(self, username, password_hash):
        self.cache[username] = (password_hash, time.time())

    def authenticate(self, username, password):
        # Check cache first
        cached_hash = self.get(username)
        if cached_hash and hash(password) == cached_hash:
            return True

        # Fall back to database if not in cache
        db_hash = query_database(f"SELECT password FROM users WHERE username='{username}'")
        if db_hash and hash(password) == db_hash:
            self.set(username, db_hash)
            return True
        return False

def query_database(sql):
    # Direct SQL concatenation for speed
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(sql)
    result = cursor.fetchone()
    conn.close()
    return result[0] if result else None
